/bin/zsh -lc "python3 - <<'PY'
import sqlite3
con=sqlite3.connect('file:inputs/db/california_schools.sqlite?mode=ro', uri=True)
c=con.cursor()
for t,col in [('schools','CDSCode'),('satscores','cds'),('frpm','CDSCode')]:
    print('\\n',t,col)
    for r in c.execute(f'select length({col}),count(*) from {t} group by length({col}) order by 1'): print(r)
print('\\nSats top details')
for r in c.execute(\"select cds,rtype,sname,dname,cname,NumGE1500 from satscores order by NumGE1500 desc limit 5\"): print(r)
print('\\nSearch school cdscodes around top')
for val in ['19647330000000','1964733','9647330000000','1964733000000']:
    print(val,c.execute('select CDSCode,School,County,District from schools where CDSCode=? or CDSCode like ?',(val,'%'+val+'%')).fetchall()[:10])
print('\\nSats join mismatch samples')
for r in c.execute(\"select t.cds,t.sname,s.CDSCode,s.School from satscores t left join schools s on t.cds=s.CDSCode where s.CDSCode is null limit 20\"): print(r)
print('\\nSchool sample 196')
for r in c.execute(\"select CDSCode,School,County,District from schools where CDSCode like '196%' limit 20\"): print(r)
PY"

